"""Turn coordinator-rewrite-plan.md into the phone page: one section per ## heading,
a Select button per section, references at the bottom of each section, outside the selection."""
import html, re, sys

src, out = sys.argv[1], sys.argv[2]
lines = open(src, encoding='utf-8').read().split('\n')

def inline(t):
    t = html.escape(t, quote=False)
    t = re.sub(r'\[([^\]]+)\]\((https://[^)]+)\)', r'<a href="\2">\1</a>', t)
    t = re.sub(r'`([^`]+)`', r'<code>\1</code>', t)
    t = re.sub(r'\*\*([^*]+)\*\*', r'<strong>\1</strong>', t)
    return t

# split: header comment, title, intro, glossary, sections
i = 0
while not lines[i].startswith('# '):
    i += 1
title = lines[i][2:].strip(); i += 1
intro, gloss = [], []
while not lines[i].startswith('## '):
    l = lines[i]
    if l.startswith('**') and l.endswith('**') and i + 1 < len(lines) and lines[i + 1].startswith(': '):
        gloss.append((l.strip('*'), lines[i + 1][2:])); i += 2; continue
    if l.strip() and l.strip() != 'Words used here:':
        intro.append(l)
    i += 1

sections = []
cur = None
for l in lines[i:]:
    if l.startswith('## '):
        cur = {'title': l[3:].strip(), 'body': []}; sections.append(cur)
    else:
        cur['body'].append(l)

def render_body(body):
    """Render a section's body; return (main_html, refs_html)."""
    main, refs = [], []
    target = main
    stack = []  # list of (indent, tag)
    open_li = []  # whether an li is open at each depth

    def close_to(depth):
        while len(stack) > depth:
            target.append('</li>')
            ind, tag = stack.pop()
            target.append(f'</{tag}>')

    for raw in body:
        if raw.strip() == '**References**':
            close_to(0); target = refs; continue
        if not raw.strip():
            continue
        m_ol = re.match(r'^(\d+)\. (.*)$', raw)
        m_ul = re.match(r'^( +)- (.*)$', raw)
        if m_ol:
            num, text = int(m_ol.group(1)), m_ol.group(2)
            if stack and stack[0][1] == 'ol':
                close_to(1); target.append('</li>')
            else:
                close_to(0)
                target.append(f'<ol start="{num}">' if num != 1 else '<ol>')
                stack.append((0, 'ol'))
            target.append(f'<li>{inline(text)}')
            continue
        if m_ul:
            ind, text = len(m_ul.group(1)), m_ul.group(2)
            depth = 2 if ind >= 5 else 1
            if len(stack) > depth:
                close_to(depth + 1); target.append('</li>')
            elif len(stack) == depth:
                target.append('<ul>'); stack.append((ind, 'ul'))
            target.append(f'<li>{inline(text)}')
            continue
        # plain paragraph
        close_to(0)
        target.append(f'<p class="group">{inline(raw)}</p>' if raw.rstrip().endswith(':') else f'<p>{inline(raw)}</p>')
    close_to(0)
    return '\n'.join(main), '\n'.join(refs)

def fix(seq):
    # close_to leaves a trailing </li> before list close; normalise the li/ol nesting
    return seq

parts = []
nav = []
for n, s in enumerate(sections, 1):
    m = re.match(r'^(\d+)\. (.*)$', s['title'])
    num, name = (m.group(1), m.group(2)) if m else (str(n), s['title'])
    sid = f'sec{num}'
    nav.append(f'<li><a href="#{sid}">{inline(name)}</a></li>')
    main, refs = render_body(s['body'])
    block = [f'<section id="{sid}" class="part">', f'<h2><span class="num">{num}</span>{inline(name)}</h2>', main]
    if refs:
        block.append('<div class="refs"><p class="refs-title">References</p>\n' + refs + '\n</div>')
    block.append('</section>')
    parts.append('\n'.join(block))

intro_html = '\n'.join(f'<p class="standfirst">{inline(p)}</p>' for p in intro)
gloss_html = '\n'.join(f'<div><dt>{html.escape(t)}</dt><dd>{inline(d)}</dd></div>' for t, d in gloss)

head = open(sys.argv[3], encoding='utf-8').read()
page = head + f'''
<div class="page">
<header class="masthead">
<p class="eyebrow">Fortress revival &middot; 2026-10-13</p>
<h1>Coordinator Rewrite Plan</h1>
{intro_html}
</header>

<nav class="parts" aria-label="Sections">
<h2>Six sections</h2>
<ol>
{chr(10).join(nav)}
</ol>
</nav>

<div class="intro">
<p>Words used here:</p>
<dl class="gloss">
{gloss_html}
</dl>
</div>

{chr(10).join(parts)}

<footer class="colophon">
<p>Written from the record, read only. The same text is committed as <a href="https://github.com/palimondo/fortress/blob/main/explorations/coordinator/process-engineering/coordinator-rewrite-plan.md">the plan in the repository</a>.</p>
</footer>
</div>

<script>
document.querySelectorAll('section.part').forEach(function (sec) {{
  var h = sec.querySelector('h2');
  if (!h) return;
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'sel';
  b.setAttribute('aria-label', 'Select this section to have it read aloud');
  h.appendChild(b);
  b.addEventListener('click', function (e) {{
    e.preventDefault();
    var r = document.createRange();
    r.setStart(h, 0);
    var refs = sec.querySelector('.refs');
    if (refs) r.setEndBefore(refs); else r.setEnd(sec, sec.childNodes.length);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  }});
}});
</script>
'''
open(out, 'w', encoding='utf-8').write(page)

